const toggle=$('#toc-toggle');
if(toggle){if(innerWidth<=760)document.body.classList.add('toc-hidden');const sync=()=>toggle.setAttribute('aria-expanded',String(!document.body.classList.contains('toc-hidden')));sync();toggle.onclick=()=>{document.body.classList.toggle('toc-hidden');sync()};$$('.toc a').forEach(a=>a.onclick=()=>{if(innerWidth<=760){document.body.classList.add('toc-hidden');sync()}});$('#toc-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();let n=0;$$('.toc a').forEach(a=>{a.hidden=!a.textContent.toLowerCase().includes(q);if(!a.hidden)n++});$('#search-empty').hidden=!!n};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.add('toc-hidden');sync()}});const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('.toc a').forEach(a=>{const on=a.hash==='#'+e.target.id;a.classList.toggle('current',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-12% 0px -65% 0px'});$$('main section').forEach(s=>observer.observe(s));}
