$('#focus')?.addEventListener('click',()=>{document.body.classList.toggle('focus-mode');$('#focus').setAttribute('aria-pressed',String(document.body.classList.contains('focus-mode')));if(document.body.classList.contains('focus-mode'))$('#point1').scrollIntoView();});
