addEventListener('scroll',()=>{const p=$('#progress');if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=(max>0?scrollY/max*100:0)+'%'}},{passive:true});
let speaking=false,utterance=null,queue=[],speechIndex=0;const readButton=$('#read'),status=$('#speech-status');
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();speaking=false;queue=[];if(readButton)readButton.textContent='▷ 朗读';if(status)status.textContent='朗读已停止。'}
function nextSpeech(){if(!speaking)return;if(speechIndex>=queue.length){stopSpeech();if(status)status.textContent='朗读完成。';return}utterance=new SpeechSynthesisUtterance(queue[speechIndex]);utterance.lang='zh-CN';utterance.rate=.88;utterance.onend=()=>{speechIndex++;nextSpeech()};utterance.onerror=()=>{stopSpeech();if(status)status.textContent='当前设备语音不可用，请直接阅读正文。'};speechSynthesis.speak(utterance)}
readButton?.addEventListener('click',()=>{if(!('speechSynthesis'in window)){if(status)status.textContent='当前浏览器不支持系统语音，请阅读正文。';return}if(speaking){stopSpeech();return}const texts=$$('.creed-text p').length?$$('.creed-text p'):$$('.sermon h2,.sermon>p');queue=texts.map(p=>p.textContent.trim()).filter(Boolean).flatMap(t=>t.match(/[^。！？；]+[。！？；]?/g)||[t]);speechIndex=0;speaking=true;readButton.textContent='■ 停止朗读';if(status)status.textContent='正在朗读；关闭页面会停止。';nextSpeech()});addEventListener('pagehide',stopSpeech);
$('#mask')?.addEventListener('click',()=>{const hide=!$$('.creed-text p.masked').length;$$('.creed-text p').forEach(p=>{p.classList.toggle('masked',hide);p.tabIndex=hide?0:-1;p.setAttribute('aria-label',hide?'已遮盖；按回车或点击揭示本段':p.textContent)});$('#mask').textContent=hide?'显示全文':'逐段背诵';});
$$('.creed-text p').forEach(p=>{const reveal=()=>{p.classList.remove('masked');p.tabIndex=-1;p.removeAttribute('aria-label')};p.addEventListener('click',reveal);p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();reveal()}})});
let lastCard=-1;$('#quiz-next')?.addEventListener('click',()=>{const cards=window.CARDS||[];let n=Math.floor(Math.random()*cards.length);if(n===lastCard)n=(n+1)%cards.length;lastCard=n;const [q,a]=cards[n];const box=$('#quiz-card');box.replaceChildren();const p=document.createElement('p');p.textContent=q;const d=document.createElement('details'),s=document.createElement('summary'),ans=document.createElement('div');s.textContent='揭晓答案';ans.className='answer';ans.textContent=a;d.append(s,ans);box.append(p,d)});
